// Concatena os blocos de texto do Claude (ignora blocos de web_search).
const blocos = $json.content || [];
const texto = blocos.filter(b => b.type === 'text').map(b => b.text).join('\n');
// O app (contrato.ts -> parseAnalise) faz o parse/validação estrita com zod.
const meta = $('Webhook — Entrada do Masor').first().json.body?.meta || {};
return [{ json: { analise_bruta: texto, meta } }];
